  function renderBarcodes(root){const d=D(),preset=localStorage.getItem('almezan_barcode_product'),product=d.products.find(x=>x.id===preset)||d.products[0],unit=product?.units?.[0],code=S.barcodeCode||unit?.barcode||product?.sku||'',label=S.barcodeLabel||product?.name||'',format=S.barcodeFormat||'auto';let preview='';try{preview=makeBarcode(code,format).svg}catch(e){preview=`<div class="empty-state compact-empty"><p>${esc(e.message)}</p></div>`}root.innerHTML=`${A.pageHead('منشئ الباركود','إنشاء ملصقات EAN-13 وCode 39 وطباعتها',action('print-barcodes','طباعة الملصقات','print'))}<div class="grid-2"><article class="panel"><div class="form-grid"><label class="field"><span>اختيار صنف</span><select id="barcodeProduct"><option value="">إدخال يدوي</option>${A.options(d.products,'id','name',product?.id)}</select></label><label class="field"><span>الوحدة</span><select id="barcodeUnit">${product?A.options(product.units,'id','name',unit?.id):''}</select></label><label class="field"><span>الكود</span><input id="barcodeCode" value="${esc(code)}"></label><label class="field"><span>نوع الباركود</span><select id="barcodeFormat"><option value="auto">تلقائي</option><option value="ean13">EAN-13</option><option value="code39">Code 39</option></select></label><label class="field"><span>اسم الملصق</span><input id="barcodeLabel" value="${esc(label)}"></label><label class="field"><span>عدد النسخ</span><input id="barcodeCopies" type="number" min="1" max="100" value="${num(S.barcodeCopies)||1}"></label></div><div class="first-login-note">${I('info')} للأكواد الرقمية استخدم 12 رقماً وسيحسب النظام رقم التحقق الثالث عشر.</div></article><article class="panel"><div class="panel-head"><div><h3>معاينة الملصق</h3><p>${esc(label)}</p></div></div><div class="barcode-preview"><div class="barcode-label">${preview}<strong>${esc(label)}</strong></div></div></article></div>`;$('#barcodeFormat').value=format;function update(){S.barcodeCode=$('#barcodeCode').value;S.barcodeLabel=$('#barcodeLabel').value;S.barcodeFormat=$('#barcodeFormat').value;S.barcodeCopies=num($('#barcodeCopies').value)||1;A.renderCurrent()}['barcodeCode','barcodeLabel'].forEach(id=>{$('#'+id).onchange=update});$('#barcodeFormat').onchange=update;$('#barcodeCopies').onchange=update;$('#barcodeProduct').onchange=e=>{const p=d.products.find(x=>x.id===e.target.value);if(p){localStorage.setItem('almezan_barcode_product',p.id);S.barcodeCode=p.units?.[0]?.barcode||p.sku||'';S.barcodeLabel=p.name}else{localStorage.removeItem('almezan_barcode_product')}A.renderCurrent()};$('#barcodeUnit').onchange=e=>{const p=d.products.find(x=>x.id===$('#barcodeProduct').value),u=p?.units.find(x=>x.id===e.target.value);if(u)S.barcodeCode=u.barcode||'';A.renderCurrent()}}

  function renderPrint(hash){$('#loginScreen').hidden=true;$('#appShell').hidden=true;let view=$('.print-view');if(!view){view=document.createElement('div');view.className='print-view';document.body.appendChild(view)}document.body.classList.add('printing');let html='';if(hash.startsWith('print-invoice/')){const id=hash.split('/')[1],x=D().sales.find(s=>s.id===id);if(!x){html='<p>الفاتورة غير موجودة.</p>'}else{const settings=D().settings,thermal=settings.printSize!=='a4',cls=thermal?`thermal thermal-${settings.printSize}`:'',tax=x.tax||0,logoHtml=settings.showInvoiceLogo!==false?`<div class="print-brand print-brand-${esc(settings.invoiceLogoSize||'small')}"><img src="brand-logo.png" alt="شعار البرنامج"></div>`:'',barcodeHtml=settings.showInvoiceBarcode!==false?`<div class="invoice-barcode invoice-barcode-${esc(settings.invoiceBarcodeSize||'medium')}">${code39Svg(x.number).svg}</div>`:'';html=`<section class="print-sheet ${cls}"><header class="print-header">${logoHtml}<div class="print-company-block"><h2>${esc(D().company.name)}</h2><p>${esc(D().company.legalName||'')}</p><small>${esc(D().company.address||'')} ${esc(D().company.phone||'')}</small><br><small>الرقم الضريبي: ${esc(D().company.taxNumber||'—')}</small></div><div class="print-title"><b>فاتورة مبيعات</b><h3>${esc(x.number)}</h3></div></header><div class="print-meta"><div><b>التاريخ:</b> ${A.dateFmt(x.date)}</div><div><b>العميل:</b> ${esc(x.customerName)}</div><div><b>الفرع:</b> ${esc(A.branchName(x.branchId))}</div><div><b>الكاشير:</b> ${esc(x.userName||'—')}</div></div><table class="print-table"><thead><tr><th>#</th><th>الصنف</th><th>الوحدة</th><th>الكمية</th><th>السعر</th><th>الإجمالي</th></tr></thead><tbody>${x.lines.map((l,i)=>`<tr><td>${i+1}</td><td>${esc(l.productName)}</td><td>${esc(l.unitName)}</td><td>${l.qty}</td><td>${A.money(l.unitPrice)}</td><td>${A.money(l.total)}</td></tr>`).join('')}</tbody></table><div class="print-totals"><div><span>المجموع</span><b>${A.money(x.subtotal)}</b></div><div><span>الخصم</span><b>${A.money(x.discount)}</b></div><div><span>الضريبة</span><b>${A.money(tax)}</b></div><div class="grand"><span>الإجمالي</span><b>${A.money(x.total)}</b></div><div><span>المدفوع</span><b>${A.money(x.paid)}</b></div><div><span>المتبقي</span><b>${A.money(x.due)}</b></div></div>${barcodeHtml}<footer class="print-footer">${esc(D().company.invoiceNote||'شكراً لتعاملكم معنا')}</footer></section>`}}else if(hash==='print-report'){let r;try{r=JSON.parse(localStorage.getItem('almezan_report_print'))}catch(e){}if(r)html=`<section class="print-sheet"><header class="print-header"><div class="print-brand print-brand-small"><img src="brand-logo.png" alt="شعار المحل"></div><div><h2>${esc(D().company.name)}</h2><small>${esc(D().company.legalName||'')}</small><br><small>${esc(D().company.taxNumber||'')} ${esc(D().company.phone||'')}</small></div><div class="print-title"><h3>${esc(r.title)}</h3><small>${esc(r.from)} — ${esc(r.to)}</small></div></header><table class="print-table" style="margin-top:18px"><thead><tr>${r.headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${r.rows.map(row=>`<tr>${row.map(c=>`<td>${typeof c==='number'?A.money(c):esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table><div class="print-totals"><div class="grand"><span>الملخص</span><b>${esc(r.summary)}</b></div></div><footer class="print-footer">طبع بتاريخ ${A.dateFmt(A.now(),true)}</footer></section>`}else if(hash==='print-record'){let r;try{r=JSON.parse(localStorage.getItem('almezan_record_print'))}catch(e){}if(r)html=`<section class="print-sheet"><header class="print-header"><div class="print-brand print-brand-small"><img src="brand-logo.png" alt="شعار المحل"></div><div class="print-company-block"><h2>${esc(r.company?.name||D().company.name)}</h2><p>${esc(r.company?.legalName||D().company.legalName||'')}</p><small>${esc(r.company?.phone||D().company.phone||'')} ${esc(r.company?.address||D().company.address||'')}</small><br><small>الرقم الضريبي: ${esc(r.company?.taxNumber||D().company.taxNumber||'—')}</small></div><div class="print-title"><b>تقرير سجل</b><h3>${esc(r.title||'سجل')}</h3></div></header><table class="print-table" style="margin-top:18px"><thead><tr>${(r.headers||[]).map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody><tr>${(r.values||[]).map(v=>`<td>${esc(v)}</td>`).join('')}</tr></tbody></table><footer class="print-footer">${esc(D().company.name)} — طبع بتاريخ ${A.dateFmt(A.now(),true)}</footer></section>`}else if(hash==='print-barcodes'){let p;try{p=JSON.parse(localStorage.getItem('almezan_barcode_print'))}catch(e){}if(p){const b=makeBarcode(p.code,p.format);html=`<section class="print-sheet"><div class="barcode-sheet">${Array.from({length:p.copies},()=>`<div class="barcode-label">${b.svg}<strong>${esc(p.label)}</strong></div>`).join('')}</div></section>`;document.body.classList.add('barcode-print')}}view.innerHTML=html||'<p>لا توجد بيانات للطباعة.</p>';requestAnimationFrame(()=>setTimeout(()=>window.print(),90))}

  A.registerView('accounts',renderAccounts);A.registerView('journals',renderJournals);A.registerView('reports',renderReports);A.registerView('branches',renderBranches);A.registerView('warehouses',renderWarehouses);A.registerView('employees',renderEmployees);A.registerView('audit',renderAudit);A.registerView('settings',renderSettings);A.registerView('barcodes',renderBarcodes);A.registerView('print',renderPrint);
  A.registerAction('view-account-ledger',b=>viewAccountLedger(b.dataset.id));A.registerAction('add-account',()=>openAccount());A.registerAction('edit-account',b=>openAccount(D().accounts.find(a=>a.id===b.dataset.id)));A.registerAction('delete-account',b=>{const x=D().accounts.find(a=>a.id===b.dataset.id);if(!x)return;const protectedIds=new Set(['ACC-1000','ACC-1100','ACC-1110','ACC-1120','ACC-1200','ACC-1300','ACC-1400','ACC-2000','ACC-2100','ACC-2200','ACC-2250','ACC-3000','ACC-4000','ACC-4100','ACC-5000','ACC-5100','ACC-5200']);if(protectedIds.has(x.id))return A.toast('هذا حساب أساسي للنظام؛ يمكنك تعديل اسمه لكن لا يمكن حذفه.','warning',5000);if(D().accounts.some(a=>a.parentId===x.id))return A.toast('لا يمكن حذف حساب يحتوي حسابات فرعية.','warning');if(D().journals.some(j=>j.lines.some(l=>l.accountId===x.id)))return A.toast('لا يمكن حذف حساب مستخدم في القيود.','warning');if(D().settings.defaultAccountId===x.id)return A.toast('غيّر الحساب الافتراضي قبل الحذف.','warning');A.confirmDialog('حذف الحساب',`${x.code} — ${x.name}`,()=>{D().accounts=D().accounts.filter(a=>a.id!==x.id);A.audit('حذف حساب','شجرة الحسابات',`${x.code} — ${x.name}`);A.saveDB();A.toast('تم حذف الحساب');A.renderCurrent()})});A.registerAction('account-transfer',()=>openAccountTransfer());A.registerAction('edit-account-transfer',b=>openAccountTransfer(D().journals.find(j=>j.id===b.dataset.id&&!j.automatic)));A.registerAction('add-journal',()=>openJournal());A.registerAction('edit-journal',b=>{const j=D().journals.find(j=>j.id===b.dataset.id&&!j.automatic);if(!j)return;try{A.validateOpenFinancialDate?.(j.date)}catch(e){return A.toast(e.message,'error',5000)}openJournal(j)});A.registerAction('delete-journal',b=>{const j=D().journals.find(x=>x.id===b.dataset.id);if(!j||j.automatic)return A.toast('القيود الآلية لا تُحذف مباشرة؛ اعكس المستند المصدر.','warning');try{A.validateOpenFinancialDate?.(j.date)}catch(e){return A.toast(e.message,'error',5000)}A.confirmDialog('حذف القيد اليدوي',`${j.number} — ستُعاد أرصدة الحسابات فوراً.`,()=>{D().journals=D().journals.filter(x=>x.id!==j.id);A.audit('حذف قيد يدوي','المحاسبة',j.number);A.saveDB();A.toast('تم حذف القيد وإعادة حساب الأرصدة');A.renderCurrent()})});A.registerAction('view-journal',b=>viewJournal(b.dataset.id));A.registerAction('export-journals',()=>A.exportExcel('القيود-المحاسبية',['الرقم','التاريخ','البيان','المرجع','مدين','دائن'],D().journals.map(j=>[j.number,j.date,j.description,j.reference,j.lines.reduce((a,l)=>a+num(l.debit),0),j.lines.reduce((a,l)=>a+num(l.credit),0)])));
  A.registerAction('refresh-report',()=>{S.reportFrom=$('#reportFrom').value;S.reportTo=$('#reportTo').value;A.renderCurrent()});A.registerAction('report-excel',()=>{const r=reportData(S.reportType,S.reportFrom,S.reportTo);A.exportExcel(r.title,r.headers,r.rows)});A.registerAction('report-pdf',()=>{const r=reportData(S.reportType,S.reportFrom,S.reportTo);localStorage.setItem('almezan_report_print',JSON.stringify(r));window.open('index.html#print-report','_blank')});
  A.registerAction('add-branch',()=>A.has('branches_manage')?openBranch():A.toast('لا تملك صلاحية إدارة الفروع.','error'));A.registerAction('edit-branch',b=>A.has('branches_manage')?openBranch(D().branches.find(x=>x.id===b.dataset.id)):A.toast('لا تملك صلاحية إدارة الفروع.','error'));A.registerAction('delete-branch',b=>{if(!A.has('branches_manage'))return A.toast('لا تملك صلاحية إدارة الفروع.','error');const x=D().branches.find(y=>y.id===b.dataset.id);if(!x)return;if(D().warehouses.some(w=>w.branchId===x.id)||D().sales.some(s=>s.branchId===x.id))return A.toast('لا يمكن حذف فرع مرتبط بمستودعات أو فواتير.','warning');A.confirmDialog('حذف الفرع',x.name,()=>{D().branches=D().branches.filter(y=>y.id!==x.id);A.saveDB();A.renderCurrent()})});
  A.registerAction('add-warehouse',()=>A.has('warehouses_manage')?openWarehouse():A.toast('لا تملك صلاحية إدارة المستودعات.','error'));A.registerAction('edit-warehouse',b=>A.has('warehouses_manage')?openWarehouse(D().warehouses.find(x=>x.id===b.dataset.id)):A.toast('لا تملك صلاحية إدارة المستودعات.','error'));A.registerAction('delete-warehouse',b=>{if(!A.has('warehouses_manage'))return A.toast('لا تملك صلاحية إدارة المستودعات.','error');const x=D().warehouses.find(y=>y.id===b.dataset.id);if(!x)return;if(D().stock.some(s=>s.warehouseId===x.id&&num(s.qtyBase)!==0)||D().sales.some(s=>s.warehouseId===x.id))return A.toast('يجب تصفير المخزون وعدم وجود حركات قبل الحذف.','warning');A.confirmDialog('حذف المستودع',x.name,()=>{D().warehouses=D().warehouses.filter(y=>y.id!==x.id);D().stock=D().stock.filter(s=>s.warehouseId!==x.id);A.saveDB();A.renderCurrent()})});
  A.registerAction('add-employee',()=>openEmployee());A.registerAction('edit-employee',b=>openEmployee(D().employees.find(x=>x.id===b.dataset.id)));A.registerAction('download-employee-auth',async b=>{const x=D().employees.find(y=>y.id===b.dataset.id);if(!x||x.system)return;if(!x.active)return A.toast('فعّل الموظف أولاً.','warning');b.disabled=true;try{await window.AlMezanActivation.prepareVerifiedRoleFile('employee',x,`موظف-${x.name}.mzauth`);A.toast('تم إنشاء ملف دخول الموظف.','success')}catch(e){A.toast(String(e?.message||e),'error',6000)}finally{b.disabled=false}});A.registerAction('toggle-employee',b=>{const x=D().employees.find(y=>y.id===b.dataset.id);if(x){x.active=!x.active;A.audit(x.active?'تفعيل موظف':'إيقاف موظف','الموظفون',x.name);A.saveDB();A.renderCurrent()}});A.registerAction('delete-employee',b=>{const x=D().employees.find(y=>y.id===b.dataset.id);if(!x||x.system)return;if(x.id===A.currentUser().id)return A.toast('لا يمكن حذف الحساب المستخدم حالياً.','warning');A.confirmDialog('حذف الموظف',x.name,()=>{D().employees=D().employees.filter(y=>y.id!==x.id);A.audit('حذف موظف','الموظفون',x.name);A.saveDB();A.renderCurrent()})});
  A.registerAction('export-audit',()=>A.exportExcel('سجل-العمليات',['الوقت','المستخدم','العملية','القسم','التفاصيل'],D().audit.map(x=>[x.date,x.userName,x.action,x.entity,x.details])));
  A.registerAction('backup-data',()=>{A.downloadBlob(`نسخة-الميزان-${A.today()}.json`,JSON.stringify(D(),null,2),'application/json;charset=utf-8');A.toast('تم إنشاء النسخة الاحتياطية')});A.registerAction('restore-data',()=>A.setFilePicker('.json,application/json',file=>{const reader=new FileReader();reader.onload=()=>{try{const data=JSON.parse(reader.result);if(!data||!Array.isArray(data.employees)||!Array.isArray(data.products))throw Error('الملف ليس نسخة صالحة.');A.confirmDialog('استعادة النسخة','سيتم استبدال كل البيانات الحالية بالنسخة المختارة.',()=>{A.setDB(data);A.audit('استعادة نسخة','النسخ الاحتياطي',file.name);A.toast('تمت استعادة البيانات');A.renderCurrent()},false)}catch(e){A.toast(e.message,'error')}};reader.readAsText(file)}));A.registerAction('export-all-excel',()=>A.exportExcel('ملخص-الميزان',['القسم','عدد السجلات','الإجمالي'],[['المبيعات',D().sales.length,D().sales.reduce((a,x)=>a+num(x.total),0)],['المشتريات',D().purchases.length,D().purchases.reduce((a,x)=>a+num(x.total),0)],['الأصناف',D().products.length,D().products.reduce((a,p)=>a+A.totalStock(p.id)*num(p.cost),0)],['العملاء',D().customers.length,D().customers.reduce((a,x)=>a+num(x.balance),0)],['الموردون',D().suppliers.length,D().suppliers.reduce((a,x)=>a+num(x.balance),0)]]));
  A.registerAction('reset-data',()=>A.openModal({title:'تصفير جميع بيانات النظام',submitText:'تصفير نهائي',submitIcon:'trash',submitClass:'btn-danger',body:`<div class="alert-item"><span>${I('alert')}</span><div><strong>هذا الإجراء لا يمكن التراجع عنه</strong><small>اكتب كلمة حذف في الحقل للتأكيد. يفضّل إنشاء نسخة احتياطية أولاً.</small></div></div><label class="field" style="margin-top:15px"><span>اكتب: حذف</span><input name="confirm" required></label>`,onSubmit:fd=>{if(fd.get('confirm').trim()!=='حذف')throw Error('كلمة التأكيد غير صحيحة.');const fresh=JSON.parse(JSON.stringify(D()));const base={...fresh,products:[],stock:[],sales:[],purchases:[],transfers:[],vouchers:[],cheques:[],finance:[],journals:[],heldOrders:[],audit:[],suppliers:[],representatives:[],customers:fresh.customers.filter(x=>x.system),sequences:{sale:0,purchase:0,voucher:0,journal:0,transfer:0}};A.setDB(base);A.toast('تم تصفير بيانات الحركات');A.renderCurrent()}}));
  A.registerAction('print-barcodes',()=>{const code=$('#barcodeCode')?.value||S.barcodeCode,label=$('#barcodeLabel')?.value||S.barcodeLabel,format=$('#barcodeFormat')?.value||S.barcodeFormat,copies=num($('#barcodeCopies')?.value||S.barcodeCopies)||1;try{makeBarcode(code,format);localStorage.setItem('almezan_barcode_print',JSON.stringify({code,label,format,copies}));window.open('index.html#print-barcodes','_blank')}catch(e){A.toast(e.message,'error')}});
